{
  "name": "bridge_screenshot",
  "description": "Capture inline PNG images from the main camera, framed/free viewpoints, object orbits, saved session camera bookmarks, ordered comparison sets, or a deterministic orthographic top-down view. Works in edit and play mode; temporary cameras are removed after every capture.",
  "tools": [
    {
      "name": "capture_camera_set",
      "title": "Capture Camera Set",
      "toolset": "bridge_screenshot",
      "description": "Capture 1-8 saved camera bookmarks in the exact requested order and return a labeled JSON manifest followed by one inline PNG per bookmark. Captures are capped at 1600x1200 and eight million aggregate pixels. Every run becomes the session baseline for the same bookmark and settings; comparePrevious uses SkiaSharp RGBA metrics against that prior capture. renderUI defaults false for stable comparisons. Occlusion checks use physics traces and are diagnostic: they never move the saved camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "names": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Saved bookmark names in desired output order (1-8, no duplicates)."
          },
          "comparePrevious": {
            "type": "boolean",
            "description": "Compare each image with the previous session capture using the same name, dimensions, and renderUI setting.",
            "default": false
          },
          "diffThreshold": {
            "type": "integer",
            "description": "Per-channel threshold (0-255) used for changedPixelPercent. Default 8.",
            "default": 8
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels (16-1600). Default 960.",
            "default": 960
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels (16-1200). Default 540.",
            "default": 540
          },
          "renderUI": {
            "type": "boolean",
            "description": "Include screen-space UI. Defaults false for deterministic visual comparisons.",
            "default": false
          },
          "checkOcclusion": {
            "type": "boolean",
            "description": "Trace from camera to lookAt and report blocking physics geometry. Default true.",
            "default": true
          }
        },
        "required": [
          "names"
        ]
      }
    },
    {
      "name": "capture_topdown",
      "title": "Capture Topdown",
      "toolset": "bridge_screenshot",
      "description": "Capture a deterministic orthographic top-down PNG over a GameObject or explicit world center. Returns a JSON manifest followed by the inline image. The manifest records the fixed camera pose, ground-plane bounds, screen axes, and world-units-per-pixel so agents can place or measure objects from the image. renderUI defaults false; dimensions are capped at 1600x1200.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "targetId": {
            "type": "string",
            "description": "GameObject GUID whose bounds determine center, ground Z, and default worldHeight."
          },
          "center": {
            "type": "string",
            "description": "Explicit top-down center as \"x,y,z\"; use instead of targetId."
          },
          "worldHeight": {
            "type": "number",
            "description": "Vertical ground-plane span in world units (screen-up/world +X). Defaults to aspect-aware target bounds + 25%, or 1024 for explicit center."
          },
          "cameraHeight": {
            "type": "number",
            "description": "Camera height above center. Does not change orthographic scale. Defaults to worldHeight*2 with additional clearance above tall targets."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels (16-1600). Default 1024.",
            "default": 1024
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels (16-1200). Default 1024.",
            "default": 1024
          },
          "renderUI": {
            "type": "boolean",
            "description": "Include screen-space UI. Default false.",
            "default": false
          }
        },
        "required": []
      }
    },
    {
      "name": "capture_view",
      "title": "Capture View",
      "toolset": "bridge_screenshot",
      "description": "Screenshot the scene from a chosen viewpoint and return it as an inline PNG image. Pass id to auto-frame a GameObject (3/4 elevated view sized to its bounds), or position (+ lookAt or rotation) for a free camera. With neither, captures the main camera view. Uses a temporary camera that is removed afterwards — the scene is left unchanged. KNOWN CAPTURE LIMITS (engine, not bridge): text in ScreenPanel/Razor labels may rasterise as solid boxes (the font atlas is not resolved for the capture pass — images and layout are correct, so a blank HUD here is NOT a HUD bug; verify text another way), and Terrain renders as a truncated ribbon from any temporary camera because its clipmap centres on the editor/main camera — verify terrain scenes with take_screenshot or in play mode.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "GUID of a GameObject to auto-frame (from get_scene_hierarchy or find_objects)."
          },
          "position": {
            "type": "string",
            "description": "Camera position as \"x,y,z\"."
          },
          "lookAt": {
            "type": "string",
            "description": "Point to aim the camera at, as \"x,y,z\"."
          },
          "rotation": {
            "type": "string",
            "description": "Camera rotation as \"pitch,yaw,roll\" degrees (alternative to lookAt)."
          },
          "fov": {
            "type": "number",
            "description": "Field of view in degrees. Default is the camera's default."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels (16-3840). Default 1280.",
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels (16-2160). Default 720.",
            "default": 720
          },
          "renderUI": {
            "type": "boolean",
            "description": "Include screen-space UI in the capture. Default true.",
            "default": true
          }
        },
        "required": []
      }
    },
    {
      "name": "delete_camera_bookmark",
      "title": "Delete Camera Bookmark",
      "toolset": "bridge_screenshot",
      "description": "Delete one session-scoped camera bookmark and its comparison baselines. Returns deleted=false when the name was already absent. Use list_camera_bookmarks to inspect what remains.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Bookmark name to delete (case-insensitive)."
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "name": "list_camera_bookmarks",
      "title": "List Camera Bookmarks",
      "toolset": "bridge_screenshot",
      "description": "List all session-scoped camera bookmarks in stable name order. Returns each resolved position, rotation, optional lookAt/target, FOV, and save time. Read-only; bookmarks reset on addon hotload or editor restart. Feed names into capture_camera_set.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "save_camera_bookmark",
      "title": "Save Camera Bookmark",
      "toolset": "bridge_screenshot",
      "description": "Save or replace a named camera bookmark in editor-session memory. Pass targetId to save the bridge's deterministic framed view of a GameObject, position plus lookAt/rotation for an explicit pose, or omit both to snapshot the current main camera. Returns the resolved pose. Bookmarks reset on addon hotload or editor restart; list them with list_camera_bookmarks and capture an ordered group with capture_camera_set.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Bookmark name (case-insensitive, 1-64 characters)."
          },
          "targetId": {
            "type": "string",
            "description": "GameObject GUID to resolve into a deterministic framed pose."
          },
          "position": {
            "type": "string",
            "description": "Explicit camera position as \"x,y,z\"."
          },
          "lookAt": {
            "type": "string",
            "description": "World point to aim at as \"x,y,z\"; pair with position."
          },
          "rotation": {
            "type": "string",
            "description": "Explicit camera rotation as \"pitch,yaw,roll\"; alternative to lookAt."
          },
          "fov": {
            "type": "number",
            "description": "Field of view in degrees (clamped 1-179). Defaults to 80, or the main camera FOV when snapshotting it."
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "name": "screenshot_from",
      "title": "Screenshot From",
      "toolset": "bridge_screenshot",
      "description": "Frame a GameObject or a free camera position and return the shot as an inline PNG image. Same as capture_view (kept under its historical name — existing workflows use it), with the same capture limits: UI text may rasterise as boxes, and Terrain renders truncated from a temporary camera (clipmap centres on the main camera) — verify terrain via take_screenshot.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "GUID of a GameObject to auto-frame."
          },
          "position": {
            "type": "string",
            "description": "Camera position as \"x,y,z\"."
          },
          "lookAt": {
            "type": "string",
            "description": "Point to aim the camera at, as \"x,y,z\"."
          },
          "rotation": {
            "type": "string",
            "description": "Camera rotation as \"pitch,yaw,roll\" degrees."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels. Default 1280.",
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels. Default 720.",
            "default": 720
          }
        },
        "required": []
      }
    },
    {
      "name": "screenshot_orbit",
      "title": "Screenshot Orbit",
      "toolset": "bridge_screenshot",
      "description": "Capture a GameObject from several angles in ONE call — orbits around the object and returns every angle as an inline PNG image, so 3D work can be verified from multiple sides instead of guessed from one. Temporary-camera limits apply: Terrain renders as a truncated ribbon (clipmap centres on the main camera) and UI text may rasterise as boxes.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "GUID of the GameObject to orbit."
          },
          "shots": {
            "type": "integer",
            "description": "Number of angles around the object (2-8). Default 4.",
            "default": 4
          },
          "elevation": {
            "type": "number",
            "description": "Camera height factor: 0 = level with the object, 1 = high above. Default 0.4.",
            "default": 0.4
          },
          "distance": {
            "type": "number",
            "description": "Camera distance in units. Default: auto from the object's bounds."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels. Default 1280.",
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels. Default 720.",
            "default": 720
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "take_screenshot",
      "title": "Take Screenshot",
      "toolset": "bridge_screenshot",
      "description": "Screenshot the scene's main camera view (the player's view in play mode) and return it as an inline PNG image. To frame a specific object or position instead, use capture_view or screenshot_orbit. KNOWN CAPTURE LIMIT (engine, not bridge): text in ScreenPanel/Razor labels may rasterise as solid boxes while images and layout are correct — a blank HUD in a capture is NOT a HUD bug; verify text another way (e.g. a Log.Info of the bound value).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels (16-3840). Default 1280.",
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels (16-2160). Default 720.",
            "default": 720
          },
          "renderUI": {
            "type": "boolean",
            "description": "Include screen-space UI (HUD) in the capture. Default true.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    }
  ]
}
